/* ─── helpers ─── */
export function qaSlug(q: string): string {
  return q
    .toLowerCase()
    .replace(/[—–]/g, " ")
    .replace(/[^a-z0-9\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .slice(0, 80)
    .replace(/-$/, "") || "tarot-question";
}

export const CAT_LABELS: Record<string, string> = {
  reality: "Are & Is Tarot Real, Evil or Against Faith?",
  is: "Is / Does / Will Tarot Work?",
  "can-i": "Can I Use Tarot Cards For Myself?",
  can: "Can Tarot Cards Predict, Curse or Harm?",
  "how-do": "How Do Tarot Cards Work?",
  how: "How Tarot Cards Are Read & Used",
  identity: "What Tarot Card Am I? Zodiac & Personal Cards",
  should: "Should I Buy, Gift, Shuffle or Trust?",
  when: "When Were Tarot Cards Invented & When To Read",
  where: "Where Tarot Cards Come From, Where To Buy & Where To Find Them",
  why: "Why Tarot Accurate, Fake, Dangerous or Good",
};

export const CAT_ORDER = ["reality", "is", "can-i", "can", "how-do", "how", "identity", "should", "when", "where", "why"];

/** Flattened + slug-deduped entry list in category order. */
export const QA_ALL: (QAEntry & { slug: string })[] = (() => {
  const out: (QAEntry & { slug: string })[] = [];
  const seen = new Set<string>();
  for (const cat of CAT_ORDER) {
    for (const e of QA_HOME) {
      if (e.cat !== cat) continue;
      const slug = qaSlug(e.q);
      if (seen.has(slug)) continue;
      seen.add(slug);
      out.push({ ...e, slug });
    }
  }
  return out;
})();

export function getQA(slug: string): (QAEntry & { slug: string }) | undefined {
  return QA_ALL.find((e) => e.slug === slug);
}
